package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

class LmdbAdjacencyArenaCatalogTest {

	private static final long TEST_REGION_BYTES = 4096;

	@Test
	void packAndUnpackRoundTripForSlotZero() {
		try (LmdbAdjacencyArena base = new LmdbAdjacencyArena(TEST_REGION_BYTES);
				LmdbAdjacencyArenaCatalog catalog = LmdbAdjacencyArenaCatalog.of(base)) {
			long handle = catalog.packHandle(0, 42);

			assertThat(handle).isEqualTo(42);
			assertThat(catalog.unpackSlot(handle)).isZero();
			assertThat(catalog.unpackLocalRef(handle)).isEqualTo(42);
			assertThat(catalog.arena(0)).isSameAs(base);
			assertThat(catalog.size()).isEqualTo(1);
		}
	}

	@Test
	void slot253IsTheLastOrdinaryArenaAndSlots254And255RemainReserved() {
		try (LmdbAdjacencyArena base = new LmdbAdjacencyArena(TEST_REGION_BYTES)) {
			assertThat(LmdbAdjacencyArenaCatalog.MAX_SLOTS).isEqualTo(254);
			List<LmdbAdjacencyArenaCatalog> catalogs = new ArrayList<>();
			LmdbAdjacencyArenaCatalog catalog = LmdbAdjacencyArenaCatalog.of(base);
			catalogs.add(catalog);
			for (int slot = 1; slot < LmdbAdjacencyArenaCatalog.MAX_SLOTS; slot++) {
				catalog = catalog.appendRetained(base);
				catalogs.add(catalog);
			}

			assertThat(catalog.size()).isEqualTo(254);
			long handle = catalog.packHandle(253, LmdbAdjacencyArena.MAX_U40_VALUE);
			assertThat(handle).isPositive();
			assertThat(catalog.unpackSlot(handle)).isEqualTo(253);
			assertThat(catalog.unpackLocalRef(handle)).isEqualTo(LmdbAdjacencyArena.MAX_U40_VALUE);

			LmdbAdjacencyArenaCatalog full = catalog;
			assertThatThrownBy(() -> full.appendRetained(base)).isInstanceOf(IllegalStateException.class);
			assertThatIllegalArgumentException()
					.isThrownBy(() -> full.packHandle(LmdbAdjacencyArenaCatalog.CSF_SLOT, 1));
			assertThatIllegalArgumentException()
					.isThrownBy(() -> full.packHandle(LmdbAdjacencyRunCodec.CHUNK_SLOT_SELF, 1));

			catalogs.forEach(LmdbAdjacencyArenaCatalog::close);
			assertThat(base.isClosed()).isFalse();
		}
	}

	@Test
	void handlesAreAlwaysPositiveAndSeparateFromTheNegativeSentinels() {
		try (LmdbAdjacencyArena base = new LmdbAdjacencyArena(TEST_REGION_BYTES);
				LmdbAdjacencyArenaCatalog catalog = LmdbAdjacencyArenaCatalog.of(base)) {
			long minHandle = catalog.packHandle(0, 1);
			long maxHandle = catalog.packHandle(0, LmdbAdjacencyArena.MAX_U40_VALUE);

			assertThat(minHandle).isPositive();
			assertThat(maxHandle).isPositive();
			// NOT_FOUND = -1 and NOT_COVERED = -2 can never be produced
			assertThat(minHandle).isNotEqualTo(-1L).isNotEqualTo(-2L);

			assertThatIllegalArgumentException().isThrownBy(() -> catalog.unpackSlot(-1));
			assertThatIllegalArgumentException().isThrownBy(() -> catalog.unpackSlot(-2));
			assertThatIllegalArgumentException().isThrownBy(() -> catalog.unpackSlot(0));
			assertThatIllegalArgumentException().isThrownBy(() -> catalog.unpackSlot(1L << 48));
		}
	}

	@Test
	void packHandleValidatesSlotAndLocalReference() {
		try (LmdbAdjacencyArena base = new LmdbAdjacencyArena(TEST_REGION_BYTES);
				LmdbAdjacencyArenaCatalog catalog = LmdbAdjacencyArenaCatalog.of(base)) {
			assertThatIllegalArgumentException().isThrownBy(() -> catalog.packHandle(-1, 1));
			assertThatIllegalArgumentException().isThrownBy(() -> catalog.packHandle(1, 1)); // slot beyond size
			assertThatIllegalArgumentException().isThrownBy(() -> catalog.packHandle(0, 0)); // null reference
			assertThatIllegalArgumentException()
					.isThrownBy(() -> catalog.packHandle(0, LmdbAdjacencyArena.MAX_U40_VALUE + 1));
		}
	}

	@Test
	void appendPreservesExistingSlotsAndRetainsOwners() {
		LmdbAdjacencyArena base = new LmdbAdjacencyArena(TEST_REGION_BYTES);
		LmdbAdjacencyArena delta = new LmdbAdjacencyArena(TEST_REGION_BYTES);

		LmdbAdjacencyArenaCatalog first = LmdbAdjacencyArenaCatalog.of(base);
		LmdbAdjacencyArenaCatalog second = first.appendRetained(delta);

		assertThat(second.size()).isEqualTo(2);
		assertThat(second.arena(0)).isSameAs(base);
		assertThat(second.arena(1)).isSameAs(delta);
		// the first catalog is unchanged
		assertThat(first.size()).isEqualTo(1);

		// creator closes; the catalogs keep both arenas alive
		base.close();
		delta.close();
		assertThat(base.isClosed()).isFalse();
		assertThat(delta.isClosed()).isFalse();

		first.close();
		assertThat(base.isClosed()).isFalse(); // still retained by the second catalog

		second.close();
		assertThat(base.isClosed()).isTrue();
		assertThat(delta.isClosed()).isTrue();

		// closing a catalog releases its owner references exactly once
		second.close();
		assertThat(base.ownerCount()).isZero();
	}

	@Test
	void closedCatalogRejectsAccess() {
		LmdbAdjacencyArena base = new LmdbAdjacencyArena(TEST_REGION_BYTES);
		LmdbAdjacencyArenaCatalog catalog = LmdbAdjacencyArenaCatalog.of(base);
		catalog.close();

		assertThatThrownBy(() -> catalog.arena(0)).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(() -> catalog.appendRetained(base)).isInstanceOf(IllegalStateException.class);
		base.close();
	}
}
